   586	    constexpr long long matrix_elements = 256LL * 256LL;
   587	    const int sample = blockIdx.x;
   588	    const int task = blockIdx.y;
   589	    const int tile_row = task >> 1;
   590	    const int tile_col = (task + 1) >> 1;
   591	    const long long accumulator_index =
   592	        sample * matrix_elements + 3 * 64 * 256 + 3 * 64
   593	        + tile_row * 32 * 256 + tile_col * 32;
   594	    const long long operand_index =
   595	        sample * matrix_elements + 2 * 64 * 256 + 3 * 64;
