   597	    const int fp32_row = threadIdx.x >> 3;
   598	    const int fp32_col = (threadIdx.x & 7) * 4;
   599	    const unsigned accumulator_base = static_cast<unsigned>(
   600	        __cvta_generic_to_shared(accumulator));
