   602	    for (int load = 0; load < 2; ++load) {
   603	        const int current_row = fp32_row + load * 16;
   604	        const unsigned shared_offset = static_cast<unsigned>(
   605	            (current_row * fp32_ld + fp32_col) * sizeof(float));
   606	        const unsigned destination_shared =
   607	            accumulator_base + shared_offset;
   608	        const float* source_global =
   609	            output + accumulator_index + current_row * output_ld + fp32_col;
   610	        asm volatile(
   611	            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
   612	            :: "r"(destination_shared), "l"(source_global));
   613	    }
